def semantic_function(ctx):
    '''Predict the pressure exerted by a perfect gas from its amount, species, volume and temperature.'''
    narrate(ctx, 'Predicting the pressure of a perfect gas from its amount, volume and temperature using pV = nRT')
    n_mol = load(ctx, 'the amount of substance of the gas in mol', d_type=float)
    species = load(ctx, 'the chemical species of the gas with its physical state', d_type=str)
    volume_text = load(ctx, 'the volume of the container holding the gas with unit', d_type=str)
    temperature_text = load(ctx, 'the temperature of the gas with unit', d_type=str)
    narrate(ctx, f'Loaded {n_mol} mol of {species} in a container of volume {volume_text} at temperature {temperature_text}')
    check = do(ctx, 'Validate the amount, species, volume and temperature against the perfect gas validity ranges', payloads={'the amount of substance of the gas in mol': n_mol, 'the chemical species of the gas with its physical state': species, 'the volume of the container holding the gas with unit': volume_text, 'the temperature of the gas with unit': temperature_text})
    valid = load(check, 'inputs are valid for the perfect gas model', d_type=bool, ctx=ctx)
    message = load(check, 'validation message', d_type=str, ctx=ctx)
    narrate(ctx, message)
    if not valid:
        raise ValueError(message)
    temp_res = do(ctx, 'Convert a temperature given in degrees Celsius or kelvin to thermodynamic temperature in kelvin', payloads={'the temperature of the gas with unit': temperature_text})
    T_K = load(temp_res, 'temperature in K', d_type=float, ctx=ctx)
    narrate(ctx, f'Thermodynamic temperature: {T_K} K')
    vol_res = do(ctx, 'Convert a volume with unit to SI volume in cubic metres', payloads={'the volume of the container holding the gas with unit': volume_text})
    V_m3 = load(vol_res, 'volume in m3', d_type=float, ctx=ctx)
    narrate(ctx, f'Volume in SI units: {V_m3} m3')
    p_res = do(ctx, 'Compute the perfect gas pressure p = nRT/V in SI units from the amount, temperature and volume.', payloads={'the amount of substance of the gas in mol': n_mol, 'temperature in K': T_K, 'volume in m3': V_m3})
    p_pa = load(p_res, 'pressure in Pa', d_type=float, ctx=ctx)
    narrate(ctx, f'Perfect gas pressure: {p_pa:.5g} Pa')
    units = do(ctx, 'Convert a pressure in pascals to atmospheres and megapascals for reporting', payloads={'pressure in Pa': p_pa})
    p_atm = load(units, 'pressure in atm', d_type=float, ctx=ctx)
    p_mpa = load(units, 'pressure in MPa', d_type=float, ctx=ctx)
    narrate(ctx, f'Pressure: {p_mpa:.3g} MPa = {p_atm:.3g} atm')
    cc = do(ctx, 'Cross-check a perfect gas pressure by recomputing it with the gas constant in L atm K-1 mol-1', payloads={'the amount of substance of the gas in mol': n_mol, 'temperature in K': T_K, 'the volume of the container holding the gas with unit': volume_text, 'pressure in Pa': p_pa})
    agree = load(cc, 'agreement of the two pressure computations', d_type=bool, ctx=ctx)
    narrate(ctx, 'Cross-check agrees with the SI result' if agree else 'Cross-check disagrees with the SI result')
    return {'pressure of the gas in MPa': p_mpa, 'pressure of the gas in Pa': p_pa, 'pressure of the gas in atm': p_atm, 'cross-check agreement': agree}